choose.when:
UPDATE ${msg_table}
SET RECVTIME = DATE_FORMAT(STR_TO_DATE('${result_time}', '%Y-%m-%d %H:%i:%s'),'%Y%m%d%H%i%s'),
    ERRCODE = '${result}',
    RESULT  = '${status}'
WHERE SEQNO = '${msgid}';

INSERT INTO ${log_table}
SELECT *
FROM ${msg_table}
WHERE SEQNO = '${msgid}';

INSERT INTO ${log_table}
SELECT *
FROM ${msg_table}
WHERE SEQNO = '${msgid}';

choose.otherwise:
INSERT INTO ${log_table}
SELECT *
FROM ${msg_table}
WHERE SEQNO = '${msgid}';

choose.when:
select count(1) as cnt
from ${msg_table}
where RESULT = 'C'

select count(1) as cnt
from ${msg_table}
where RESULT = 'C'

choose.otherwise:
select count(1) as cnt
from ${msg_table}
where RESULT = 'C'

choose.when:
UPDATE ${msg_table}
SET RETRY = '${group_no}'
WHERE RESULT = 'C'
LIMIT 500;

INSERT INTO ${log_table}
SELECT *
FROM ${msg_table}
WHERE RETRY = '${group_no}';

INSERT INTO ${log_table}
SELECT *
FROM ${msg_table}
WHERE RETRY = '${group_no}';

choose.otherwise:
INSERT INTO ${log_table}
SELECT *
FROM ${msg_table}
WHERE RETRY = '${group_no}';
